# ---------- CLI ----------

@dataclass
class Options:
    output: Optional[str] = None
    no_color: bool = False
    repl: bool = False
    completions: Optional[str] = None
    test: Optional[str] = None
    test_file: Optional[str] = None
    input_path: Optional[str] = None


def clap_error(msg: str, usage: Optional[str] = None) -> int:
    sys.stderr.write(f"error: {msg}\n\n")
    if usage:
        sys.stderr.write(f"Usage: {usage}\n\n")
    sys.stderr.write("For more information, try '--help'.\n")
    return 2


def parse_args(argv: List[str]) -> Tuple[Optional[Options], int]:
    opts = Options()
    positionals: List[str] = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--":
            positionals.extend(argv[i + 1:])
            break
        if arg in ("-h", "--help"):
            sys.stdout.write(HELP_TEXT)
            return None, 0
        if arg in ("-V", "--version"):
            sys.stdout.write(VERSION_TEXT)
            return None, 0
        if arg in ("-n", "--no-color"):
            opts.no_color = True
            i += 1
            continue
        if arg in ("-r", "--repl"):
            opts.repl = True
            i += 1
            continue
        if arg in ("-o", "--output", "-t", "--test", "-f", "--test-file", "--generate-completions"):
            if i + 1 >= len(argv) or argv[i + 1].startswith("-") and arg == "--generate-completions":
                name = {
                    "-o": "--output <OUTPUT_FILE_PATH>",
                    "--output": "--output <OUTPUT_FILE_PATH>",
                    "-t": "--test <test>",
                    "--test": "--test <test>",
                    "-f": "--test-file <test-file>",
                    "--test-file": "--test-file <test-file>",
                    "--generate-completions": "--generate-completions <completions>",
                }[arg]
                return None, clap_error(f"a value is required for '{name}' but none was supplied")
            if i + 1 >= len(argv):
                name = {
                    "-o": "--output <OUTPUT_FILE_PATH>", "--output": "--output <OUTPUT_FILE_PATH>",
                    "-t": "--test <test>", "--test": "--test <test>",
                    "-f": "--test-file <test-file>", "--test-file": "--test-file <test-file>",
                    "--generate-completions": "--generate-completions <completions>",
                }[arg]
                return None, clap_error(f"a value is required for '{name}' but none was supplied")
            val = argv[i + 1]
            if arg in ("-o", "--output"):
                opts.output = val
            elif arg in ("-t", "--test"):
                opts.test = val
            elif arg in ("-f", "--test-file"):
                opts.test_file = val
            else:
                opts.completions = val
            i += 2
            continue
        if arg.startswith("--output="):
            opts.output = arg.split("=", 1)[1]
            i += 1
            continue
        if arg.startswith("--test="):
            opts.test = arg.split("=", 1)[1]
            i += 1
            continue
        if arg.startswith("--test-file="):
            opts.test_file = arg.split("=", 1)[1]
            i += 1
            continue
        if arg.startswith("--generate-completions="):
            opts.completions = arg.split("=", 1)[1]
            i += 1
            continue
        if arg.startswith("-") and arg != "-":
            return None, clap_error(f"unexpected argument '{arg}' found", "executable [OPTIONS] [INPUT_FILE_PATH]")
        positionals.append(arg)
        i += 1
    if len(positionals) > 1:
        return None, clap_error(f"unexpected argument '{positionals[1]}' found", "executable [OPTIONS] [INPUT_FILE_PATH]")
    if positionals:
        opts.input_path = positionals[0]

    # Conflicts matching the observed clap messages for common combinations.
    if opts.test is not None and opts.output is not None:
        usage = "executable"
        if opts.no_color:
            usage += " --no-color"
        usage += " --test <test> <INPUT_FILE_PATH>"
        return None, clap_error("the argument '--test <test>' cannot be used with '--output <OUTPUT_FILE_PATH>'", usage)
    if opts.test_file is not None and opts.test is not None:
        usage = "executable"
        if opts.no_color:
            usage += " --no-color"
        usage += " --test-file <test-file> <INPUT_FILE_PATH>"
        return None, clap_error("the argument '--test-file <test-file>' cannot be used with '--test <test>'", usage)
    if opts.test_file is not None and opts.output is not None:
        usage = "executable"
        if opts.no_color:
            usage += " --no-color"
        usage += " --test-file <test-file> <INPUT_FILE_PATH>"
        return None, clap_error("the argument '--test-file <test-file>' cannot be used with '--output <OUTPUT_FILE_PATH>'", usage)
    if opts.completions is not None and opts.output is not None:
        return None, clap_error("the argument '--generate-completions <completions>' cannot be used with '--output <OUTPUT_FILE_PATH>'", "executable --generate-completions <completions>")
    return opts, -1


def read_source(path: Optional[str]) -> Tuple[Optional[str], Optional[str], int]:
    if path is None or path == "-":
        try:
            if path is None and sys.stdin.isatty():
                return "", None, 0
            return sys.stdin.read(), None, 0
        except Exception:
            return None, "unable read file at path -", 65
    try:
        with open(path, "r", encoding="utf-8") as f:
            return f.read(), None, 0
    except Exception:
        return None, f"unable read file at path {path}", 65


def run_repl() -> int:
    if (not sys.stdin.isatty()) or (not sys.stdout.isatty()):
        sys.stderr.write("Error: repl argument supplied with piped input or output\n")
        return 64
    # Minimal interactive REPL compatible with the compiler.  The observed binary
    # refuses non-tty pipes, which is the mode used by automated tests.
    while True:
        try:
            line = input("> ")
        except EOFError:
            break
        if line.strip() in ("exit", "quit", ".exit", ".quit"):
            break
        try:
            print(compile_melody(line))
        except SemanticError as e:
            print(f"Error: {e.message}", file=sys.stderr)
        except ParseError as e:
            print(format_parse_error(e, line), file=sys.stderr, end="")
    return 0


def main(argv: List[str]) -> int:
    opts, status = parse_args(argv)
    if opts is None:
        return status

    if opts.completions is not None:
        out, err = completion_text(opts.completions)
        if out:
            sys.stdout.write(out)
        if err:
            sys.stderr.write(err)
        return 0

    if opts.repl:
        return run_repl()

    source, err, code = read_source(opts.input_path)
    if err is not None:
        sys.stderr.write(f"Error: {err}\n")
        return code
    assert source is not None

    try:
        regex = compile_melody(source)
    except SemanticError as e:
        sys.stderr.write(f"Error: {e.message}\n")
        return 65
    except ParseError as e:
        sys.stderr.write(format_parse_error(e, source))
        return 65

    if opts.test_file is not None:
        try:
            with open(opts.test_file, "r", encoding="utf-8") as f:
                test_text = f.read()
        except Exception:
            sys.stderr.write(f"Error: unable read file at path {opts.test_file}\n")
            return 74
        try:
            matched = test_regex(regex, test_text)
        except Exception as e:
            sys.stderr.write(regex_compile_error(regex, e))
            return 65
        sys.stdout.write(f"{opts.test_file} {'matched' if matched else 'did not match'}\n")
        return 0

    if opts.test is not None:
        try:
            matched = test_regex(regex, opts.test)
        except Exception as e:
            sys.stderr.write(regex_compile_error(regex, e))
            return 65
        sys.stdout.write(f"'{opts.test}' {'matched' if matched else 'did not match'}\n")
        return 0

    if opts.output is not None:
        try:
            with open(opts.output, "w", encoding="utf-8") as f:
                f.write(regex)
        except Exception:
            sys.stderr.write(f"Error: {opts.output}\n")
            return 74
        return 0

    sys.stdout.write(regex + "\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
