#!/usr/bin/env python3
"""Clean-room reimplementation of the observed Melody CLI behavior."""
from __future__ import annotations

import os
import re
import sys
from dataclasses import dataclass
from typing import Dict, List, Optional, Tuple

HELP_TEXT = """A CLI wrapping the Melody language compiler

Usage: executable [OPTIONS] [INPUT_FILE_PATH]

Arguments:
  [INPUT_FILE_PATH]  Read from a file
                     Use '-' and or pipe input to read from stdin

Options:
  -o, --output <OUTPUT_FILE_PATH>           Write to a file
  -n, --no-color                            Print output with no color
  -r, --repl                                Start the Melody REPL
      --generate-completions <completions>  Outputs completions for the selected shell
                                            To use, write the output to the appropriate location for your shell
  -t, --test <test>                         Test the compiled regex against a string
  -f, --test-file <test-file>               Test the compiled regex against the contents of a file
  -h, --help                                Print help
  -V, --version                             Print version
"""

VERSION_TEXT = "melody_cli 0.20.0\n"

REGEX_META = set(".^$*+?()[]{}|")


class MelodyError(Exception):
    pass


class SemanticError(MelodyError):
    def __init__(self, message: str):
        self.message = message
        super().__init__(message)


class ParseError(MelodyError):
    def __init__(self, pos: int, expected: str = "root"):
        self.pos = pos
        self.expected = expected
        super().__init__(expected)


@dataclass
class Atom:
    text: str
    atom: bool = True
    kind: str = "atom"  # atom, group, assertion, variable, declaration


class Parser:
    def __init__(self, source: str):
        self.s = source
        self.n = len(source)
        self.i = 0
        self.vars: Dict[str, str] = {}

    # ---------- utilities ----------
    def eof(self) -> bool:
        return self.i >= self.n

    def starts(self, text: str) -> bool:
        return self.s.startswith(text, self.i)

    def skip_ws_comments(self) -> None:
        while self.i < self.n:
            c = self.s[self.i]
            if c.isspace():
                self.i += 1
                continue
            if self.s.startswith("/*", self.i):
                end = self.s.find("*/", self.i + 2)
                if end == -1:
                    raise ParseError(self.i, "EOI, literal, raw, not, range, quantifier_quantity, group_declaration, assertion_declaration, variable_declaration, or variable_invocation")
                self.i = end + 2
                continue
            if self.s.startswith("//", self.i) and self._line_comment_allowed(self.i):
                end = self.s.find("\n", self.i + 2)
                if end == -1:
                    self.i = self.n
                else:
                    self.i = end
                continue
            break

    def _line_comment_allowed(self, pos: int) -> bool:
        j = pos - 1
        while j >= 0 and self.s[j] in " \t\r":
            j -= 1
        return j < 0 or self.s[j] == "\n"

    def consume(self, text: str) -> bool:
        if self.s.startswith(text, self.i):
            self.i += len(text)
            return True
        return False

    def expect(self, text: str, expected: Optional[str] = None) -> None:
        if not self.consume(text):
            raise ParseError(self.i, expected or repr(text))

    def parse_identifier(self) -> str:
        start = self.i
        while self.i < self.n and (self.s[self.i].isalpha() and self.s[self.i].isascii() or self.s[self.i] == "_"):
            self.i += 1
        if self.i == start:
            raise ParseError(self.i, "identifier")
        return self.s[start:self.i]

    # ---------- entry point ----------
    def parse(self) -> str:
        out = self.parse_sequence(stop=None, either=False)
        self.skip_ws_comments()
        if not self.eof():
            raise ParseError(self.i, "EOI, literal, raw, not, range, quantifier_quantity, group_declaration, assertion_declaration, variable_declaration, or variable_invocation")
        return out

    def parse_block(self, either: bool = False) -> str:
        self.skip_ws_comments()
        if not self.consume("{"):
            raise ParseError(self.i, "block")
        content_start = self.i
        pieces: List[str] = []
        first = True
        while True:
            self.skip_ws_comments()
            if self.i < self.n and self.s[self.i] == "}":
                if first:
                    raise ParseError(self.i, "literal, raw, not, range, quantifier_quantity, group_declaration, assertion_declaration, variable_declaration, or variable_invocation")
                self.i += 1
                return "|".join(pieces) if either else "".join(pieces)
            if self.eof():
                raise ParseError(content_start, "block")
            atom = self.parse_statement()
            pieces.append(atom.text)
            first = False

    def parse_sequence(self, stop: Optional[str], either: bool) -> str:
        pieces: List[str] = []
        while True:
            self.skip_ws_comments()
            if self.eof():
                break
            if stop is not None and self.s[self.i] == stop:
                break
            atom = self.parse_statement()
            pieces.append(atom.text)
        return "|".join(pieces) if either else "".join(pieces)

    # ---------- statements ----------
    def parse_statement(self) -> Atom:
        self.skip_ws_comments()
        if self.eof():
            raise ParseError(self.i, "root")

        # Block-valued declarations/constructs first.
        if self.starts("let"):
            return self.parse_variable_declaration()
        if self.starts("match"):
            return self.parse_group()
        if self.starts("capture"):
            return self.parse_group()
        if self.starts("either"):
            return self.parse_group()
        if self.starts("ahead") or self.starts("behind"):
            return self.parse_assertion(False)
        if self.starts("not"):
            return self.parse_not_statement()
        if self.starts("lazy") or self.starts("over") or self.starts("some") or self.starts("any") or self.starts("option") or (self.i < self.n and self.s[self.i].isdigit()):
            # A leading digit may also be an ASCII range (e.g. 0 to 9;).
            rng = self.try_parse_range_statement()
            if rng is not None:
                return rng
            return self.parse_quantifier()
        # Ranges can start with many ordinary characters.
        rng = self.try_parse_range_statement()
        if rng is not None:
            return rng
        if self.s[self.i] == '"':
            atom = self.parse_literal()
            self.require_semicolon()
            return atom
        if self.s[self.i] == '`':
            atom = self.parse_raw()
            self.require_semicolon()
            return atom
        if self.s[self.i] == '<':
            atom = self.parse_symbol(False)
            self.require_semicolon()
            return atom
        if self.s[self.i] == '.':
            atom = self.parse_variable_invocation()
            self.require_semicolon()
            return atom
        raise ParseError(self.i, "root")

    def require_semicolon(self) -> None:
        self.skip_ws_comments()
        if not self.consume(";"):
            raise ParseError(self.i, "root")

    # ---------- literals ----------
    def parse_literal(self) -> Atom:
        start = self.i
        self.expect('"')
        tokens: List[str] = []
        while self.i < self.n:
            c = self.s[self.i]
            if c == '"':
                self.i += 1
                return Atom("".join(tokens), atom=(len(tokens) == 1), kind="atom")
            if c == "\\":
                if self.i + 1 >= self.n:
                    raise ParseError(start, "root")
                nxt = self.s[self.i + 1]
                if nxt == '"':
                    tokens.append('"')
                    self.i += 2
                    continue
                if nxt == "\\":
                    tokens.append("\\")
                    self.i += 2
                    continue
                if nxt in ["/", "n", "r", "t", "b", "f"]:
                    tokens.append("\\" + nxt)
                    self.i += 2
                    continue
                if nxt == "u":
                    if self.i + 6 <= self.n and all(ch in "0123456789abcdefABCDEF" for ch in self.s[self.i + 2:self.i + 6]):
                        tokens.append(self.s[self.i:self.i + 6])
                        self.i += 6
                        continue
                    raise ParseError(start, "root")
                raise ParseError(start, "root")
            # Ordinary character: escape regex metacharacters, preserve everything else.
            if c in REGEX_META:
                tokens.append("\\" + c)
            else:
                tokens.append(c)
            self.i += 1
        raise ParseError(start, "root")

    def parse_raw(self) -> Atom:
        start = self.i
        self.expect('`')
        chars: List[str] = []
        atom_count = 0
        while self.i < self.n:
            c = self.s[self.i]
            if c == '`':
                self.i += 1
                return Atom("".join(chars), atom=(atom_count == 1), kind="atom")
            if c == "\\":
                if self.i + 1 < self.n and self.s[self.i + 1] == '`':
                    chars.append('`')
                    atom_count += 1
                    self.i += 2
                    continue
                raise ParseError(start, "root")
            chars.append(c)
            atom_count += 1
            self.i += 1
        raise ParseError(start, "root")

    # ---------- symbols, ranges, not ----------
    def parse_symbol(self, negative: bool) -> Atom:
        start = self.i
        self.expect("<", "symbol_identifier")
        end = self.s.find(">", self.i)
        if end == -1:
            raise ParseError(self.i, "symbol_identifier")
        name = self.s[self.i:end]
        self.i = end + 1
        text = self.symbol_regex(name, negative)
        return Atom(text, atom=True, kind="atom")

    def symbol_regex(self, name: str, negative: bool) -> str:
        pos = self.i
        pos_map = {
            "char": ".",
            "space": " ",
            "whitespace": r"\s",
            "newline": r"\n",
            "return": r"\r",
            "tab": r"\t",
            "digit": r"\d",
            "word": r"\w",
            "alphabetic": "[a-zA-Z]",
            "alphanumeric": "[a-zA-Z0-9]",
            "boundary": r"\b",
            "start": "^",
            "end": "$",
            "null": r"\0",
            "backspace": r"[\b]",
        }
        neg_map = {
            "space": "[^ ]",
            "whitespace": r"\S",
            "newline": r"[^\n]",
            "return": r"[^\r]",
            "tab": r"[^\t]",
            "digit": r"\D",
            "word": r"\W",
            "alphabetic": "[^a-zA-Z]",
            "alphanumeric": "[^a-zA-Z0-9]",
            "boundary": r"\B",
            "null": r"[^\0]",
            "backspace": r"[^\b]",
        }
        if not negative:
            if name in pos_map:
                return pos_map[name]
            raise SemanticError("usage of an unrecognized symbol")
        if name in ("char", "start", "end"):
            raise SemanticError(f"negative {name} not allowed")
        if name in neg_map:
            return neg_map[name]
        raise SemanticError("usage of an unrecognized symbol")

    def range_from_content(self, content: str, negative: bool = False) -> Optional[str]:
        # Single-character ASCII range: <char> optional spaces "to" optional spaces <char>, nothing else
        m = re.fullmatch(r"\s*(.)\s*to\s*(.)\s*", content, flags=re.S)
        if not m:
            return None
        a, b = m.group(1), m.group(2)
        prefix = "^" if negative else ""
        return f"[{prefix}{a}-{b}]"

    def try_parse_range_statement(self) -> Optional[Atom]:
        saved = self.i
        # Find the next semicolon before a newline/block close; range statements are simple.
        semi = self.s.find(";", self.i)
        if semi == -1:
            return None
        content = self.s[self.i:semi]
        # Reject things that obviously belong to other constructs.
        if not content or content[0] in ['"', '`', '<', '.', '{', '}', '/']:
            return None
        rgx = self.range_from_content(content, negative=False)
        if rgx is None:
            return None
        self.i = semi + 1
        return Atom(rgx, atom=True, kind="atom")

    def parse_not_statement(self) -> Atom:
        self.expect("not")
        self.skip_ws_comments()
        if self.starts("ahead") or self.starts("behind"):
            return self.parse_assertion(True)
        if self.i < self.n and self.s[self.i] == '<':
            atom = self.parse_symbol(True)
            self.require_semicolon()
            return atom
        # Negative character class. Leading whitespace after `not` is skipped above; trailing
        # whitespace before ';' is part of ordinary class content, except for ranges.
        start = self.i
        semi = self.s.find(";", self.i)
        if semi == -1:
            raise ParseError(self.i, "amount or assertion_type")
        content = self.s[start:semi]
        if content == "" or content[0] in ['"', '`', '<', '{', '}', ']', '-']:
            raise ParseError(start, "amount, class_content, or assertion_type")
        rgx = self.range_from_content(content, negative=True)
        if rgx is None:
            rgx = f"[^{content}]"
        self.i = semi + 1
        return Atom(rgx, atom=True, kind="atom")

    # ---------- groups/assertions/variables ----------
    def parse_group(self) -> Atom:
        if self.starts("match"):
            self.i += len("match")
            body = self.parse_block(either=False)
            return Atom(f"(?:{body})", atom=True, kind="group")
        if self.starts("either"):
            self.i += len("either")
            body = self.parse_block(either=True)
            return Atom(f"(?:{body})", atom=True, kind="group")
        if self.starts("capture"):
            self.i += len("capture")
            self.skip_ws_comments()
            name: Optional[str] = None
            if self.i < self.n and self.s[self.i] != "{":
                name = self.parse_identifier()
                self.skip_ws_comments()
            body = self.parse_block(either=False)
            if name is None:
                return Atom(f"({body})", atom=True, kind="group")
            return Atom(f"(?<{name}>{body})", atom=True, kind="group")
        raise ParseError(self.i, "group_declaration")

    def parse_assertion(self, negative: bool) -> Atom:
        if self.starts("ahead"):
            self.i += len("ahead")
            body = self.parse_block(either=False)
            return Atom(f"(?!{body})" if negative else f"(?={body})", atom=True, kind="assertion")
        if self.starts("behind"):
            self.i += len("behind")
            body = self.parse_block(either=False)
            return Atom(f"(?<!{body})" if negative else f"(?<={body})", atom=True, kind="assertion")
        raise ParseError(self.i, "assertion_type")

    def parse_variable_declaration(self) -> Atom:
        self.expect("let")
        self.skip_ws_comments()
        if not self.consume("."):
            raise ParseError(self.i, "identifier")
        name = self.parse_identifier()
        self.skip_ws_comments()
        if not self.consume("="):
            raise ParseError(self.i, "block")
        body = self.parse_block(either=False)
        self.vars[name] = body
        return Atom("", atom=False, kind="declaration")

    def parse_variable_invocation(self) -> Atom:
        self.expect(".")
        name = self.parse_identifier()
        if name not in self.vars:
            raise SemanticError("usage of an uninitialized variable")
        return Atom(self.vars[name], atom=False, kind="variable")

    # ---------- quantifiers ----------
    def parse_quantifier(self) -> Atom:
        lazy = False
        if self.starts("lazy"):
            self.i += len("lazy")
            lazy = True
            self.skip_ws_comments()
        suffix = self.parse_quantity_suffix()
        self.skip_ws_comments()
        if not self.consume("of"):
            raise ParseError(self.i, "of")
        self.skip_ws_comments()
        target = self.parse_quantifier_target()
        if target.kind == "assertion":
            raise SemanticError("unexpected assertion in quantifier")
        if target.kind == "variable":
            raise SemanticError("unexpected variable invocation in quantifier")
        if target.kind == "declaration":
            raise SemanticError("unexpected skipped node in quantifier")
        text = target.text if target.atom else f"(?:{target.text})"
        if lazy:
            suffix += "?"
        return Atom(text + suffix, atom=True, kind="atom")

    def parse_quantity_suffix(self) -> str:
        self.skip_ws_comments()
        if self.starts("over"):
            self.i += len("over")
            self.skip_ws_comments()
            amount_s = self.parse_amount_string()
            try:
                amount = int(amount_s) + 1
            except ValueError:
                amount = 1
            return "{" + str(amount) + ",}"
        if self.i < self.n and self.s[self.i].isdigit():
            first = self.parse_amount_string()
            self.skip_ws_comments()
            if self.consume("to"):
                self.skip_ws_comments()
                second = self.parse_amount_string()
                try:
                    if int(first) > int(second):
                        raise SemanticError("usage of an invalid quantifier range")
                except ValueError:
                    pass
                return "{" + first + "," + second + "}"
            return "{" + first + "}"
        for word, suffix in [("some", "+"), ("any", "*"), ("option", "?")]:
            if self.starts(word):
                self.i += len(word)
                return suffix
        raise ParseError(self.i, "amount, some, any, option, or over")

    def parse_amount_string(self) -> str:
        start = self.i
        while self.i < self.n and self.s[self.i].isdigit():
            self.i += 1
        if self.i == start:
            raise ParseError(self.i, "amount")
        return self.s[start:self.i]

    def parse_quantifier_target(self) -> Atom:
        self.skip_ws_comments()
        if self.eof():
            raise ParseError(self.i, "literal, raw, not, range, group_declaration, assertion_declaration, variable_declaration, or variable_invocation")
        if self.starts("let"):
            return self.parse_variable_declaration()
        if self.starts("match") or self.starts("capture") or self.starts("either"):
            return self.parse_group()
        if self.starts("ahead") or self.starts("behind"):
            return self.parse_assertion(False)
        if self.starts("not"):
            return self.parse_not_statement()
        rng = self.try_parse_range_statement()
        if rng is not None:
            return rng
        if self.s[self.i] == '"':
            atom = self.parse_literal()
            self.require_semicolon()
            return atom
        if self.s[self.i] == '`':
            atom = self.parse_raw()
            self.require_semicolon()
            return atom
        if self.s[self.i] == '<':
            atom = self.parse_symbol(False)
            self.require_semicolon()
            return atom
        if self.s[self.i] == '.':
            atom = self.parse_variable_invocation()
            self.require_semicolon()
            return atom
        raise ParseError(self.i, "literal, raw, not, range, group_declaration, assertion_declaration, variable_declaration, or variable_invocation")


def compile_melody(source: str) -> str:
    return Parser(source).parse()


def format_parse_error(err: ParseError, source: str) -> str:
    pos = max(0, min(err.pos, len(source)))
    # line/column are 1-based; EOF is one past the last column.
    line_no = source.count("\n", 0, pos) + 1
    line_start = source.rfind("\n", 0, pos) + 1
    line_end = source.find("\n", pos)
    if line_end == -1:
        line_end = len(source)
    line = source[line_start:line_end]
    col = pos - line_start + 1
    pointer_spaces = " " * max(col - 1, 0)
    return (
        f"Error:  --> {line_no}:{col}\n"
        f"  |\n"
        f"{line_no} | {line}\n"
        f"  | {pointer_spaces}^---\n"
        f"  |\n"
        f"  = expected {err.expected}\n"
    )


# ---------- regex testing ----------

def js_regex_to_python(regex: str) -> str:
    # Python uses (?P<name>...) while ECMAScript uses (?<name>...).  Negative
    # lookbehind begins (?<! and must not be rewritten.
    def repl(m: re.Match[str]) -> str:
        name = m.group(1)
        return f"(?P<{name}>"
    return re.sub(r"\(\?<([A-Za-z_][A-Za-z_]*)>", repl, regex)


def test_regex(regex: str, text: str) -> bool:
    py = js_regex_to_python(regex)
    return re.search(py, text, flags=re.S) is not None


def regex_compile_error(regex: str, exc: Exception) -> str:
    msg = str(exc)
    # The original reports friendlier messages for common cases.  Match the
    # prominent observed one; otherwise pass Python's message through.
    if "unterminated character set" in msg:
        cause = "unbalanced bracket"
    elif "unknown extension ?P" in msg:
        cause = "invalid token at named capture group identifier"
    else:
        cause = msg
    return f"Error: could not compile regex\nCause: {cause}\nRegex: {regex}\n"


